    "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider     = \"prisma-client\"\n  moduleFormat = \"cjs\"\n  output       = \"../generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ================= ENUMS (9) =================\n\n// ASSUMED: matches frontend BrandId type — verify against lib/types/index.ts\nenum BrandId {\n  BIN_ESSA_SMOKING_CENTER\n  BIN_ESSA_KHIRAN\n  JM_ART_ZONE\n}\n\n// ASSUMED: matches frontend Role type — verify values/casing\nenum Role {\n  ADMIN\n  MANAGER\n  CASHIER\n  ACCOUNTANT\n}\n\n// ASSUMED: matches frontend ItemCategory — verify exact category list\nenum ItemCategory {\n  TOBACCO\n  ACCESSORIES\n  ELECTRONICS\n  ART_SUPPLIES\n  OTHER\n}\n\n// ASSUMED: matches frontend ItemVisibility\nenum ItemVisibility {\n  ALL_BRANCHES\n  SPECIFIC_BRANCHES\n}\n\n// ASSUMED: matches frontend PaymentMethod\nenum PaymentMethod {\n  CASH\n  CARD\n  CREDIT\n  BANK_TRANSFER\n}\n\n// ASSUMED: matches frontend AccountType (standard chart-of-accounts types)\nenum AccountType {\n  ASSET\n  LIABILITY\n  EQUITY\n  REVENUE\n  EXPENSE\n}\n\n// NOT explicitly in your type list — added because a real SalesInvoice needs a status.\n// FLAG: confirm this doesn't already exist under a different name in sales-invoice.ts\nenum InvoiceStatus {\n  DRAFT\n  POSTED\n  PAID\n  VOID\n}\n\n// NOT explicitly in your type list — added so JournalEntry has a lifecycle state.\n// FLAG: confirm against lib/types/index.ts JournalEntry definition\nenum JournalEntryStatus {\n  DRAFT\n  POSTED\n}\n\n// NOT explicitly in your type list — added for ItemStock audit trail readiness.\n// FLAG: only needed if you track stock movement history; otherwise can be deleted\nenum StockMovementType {\n  SALE\n  PURCHASE\n  ADJUSTMENT\n}\n\n// ================= MODELS (11) =================\n\nmodel Branch {\n  id       String  @id @default(uuid())\n  code     String  @unique // e.g. \"br-01\"\n  name     String\n  brandId  BrandId\n  address  String?\n  isActive Boolean @default(true)\n\n  users          User[]\n  itemStocks     ItemStock[]\n  customers      Customer[]\n  suppliers      Supplier[]\n  salesInvoices  SalesInvoice[]\n  journalEntries JournalEntry[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel User {\n  id           String  @id @default(uuid())\n  username     String  @unique\n  passwordHash String\n  fullName     String\n  role         Role\n  branchId     String?\n  branch       Branch? @relation(fields: [branchId], references: [id])\n  isActive     Boolean @default(true)\n\n  salesInvoices SalesInvoice[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel Item {\n  id         String         @id @default(uuid())\n  sku        String         @unique\n  barcode    String?        @unique\n  name       String\n  category   ItemCategory\n  visibility ItemVisibility @default(ALL_BRANCHES)\n  price      Decimal        @db.Decimal(10, 3) // KWD uses 3 decimal places\n  cost       Decimal        @db.Decimal(10, 3)\n  unit       String         @default(\"pcs\")\n  isActive   Boolean        @default(true)\n\n  stocks            ItemStock[]\n  salesInvoiceLines SalesInvoiceLine[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel ItemStock {\n  id       String  @id @default(uuid())\n  itemId   String\n  branchId String\n  quantity Decimal @default(0) @db.Decimal(10, 3)\n\n  item   Item   @relation(fields: [itemId], references: [id])\n  branch Branch @relation(fields: [branchId], references: [id])\n\n  updatedAt DateTime @updatedAt\n\n  @@unique([itemId, branchId])\n}\n\nmodel Customer {\n  id       String  @id @default(uuid())\n  code     String  @unique // e.g. \"cust-0001\" — FLAG: confirm code format with client\n  name     String\n  phone    String?\n  email    String?\n  address  String?\n  branchId String?\n  branch   Branch? @relation(fields: [branchId], references: [id])\n\n  salesInvoices SalesInvoice[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel Supplier {\n  id       String  @id @default(uuid())\n  code     String  @unique\n  name     String\n  phone    String?\n  email    String?\n  address  String?\n  branchId String?\n  branch   Branch? @relation(fields: [branchId], references: [id])\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel Account {\n  id   String      @id @default(uuid())\n  code String      @unique // e.g. \"1000\" for Cash\n  name String\n  type AccountType\n\n  journalEntryLines JournalEntryLine[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel JournalEntry {\n  id          String             @id @default(uuid())\n  reference   String             @unique // e.g. \"JE-0001\"\n  date        DateTime           @default(now())\n  description String?\n  status      JournalEntryStatus @default(POSTED)\n  branchId    String?\n  branch      Branch?            @relation(fields: [branchId], references: [id])\n\n  // Links back to the sale that auto-generated this entry (nullable — not all JEs come from sales)\n  salesInvoiceId String?       @unique\n  salesInvoice   SalesInvoice? @relation(fields: [salesInvoiceId], references: [id])\n\n  lines JournalEntryLine[]\n\n  createdAt DateTime @default(now())\n}\n\nmodel JournalEntryLine {\n  id             String  @id @default(uuid())\n  journalEntryId String\n  accountId      String\n  debit          Decimal @default(0) @db.Decimal(10, 3)\n  credit         Decimal @default(0) @db.Decimal(10, 3)\n\n  journalEntry JournalEntry @relation(fields: [journalEntryId], references: [id])\n  account      Account      @relation(fields: [accountId], references: [id])\n}\n\nmodel SalesInvoice {\n  id            String        @id @default(uuid())\n  invoiceNumber String        @unique // e.g. \"INV-0001\"\n  date          DateTime      @default(now())\n  customerId    String?\n  customer      Customer?     @relation(fields: [customerId], references: [id])\n  branchId      String\n  branch        Branch        @relation(fields: [branchId], references: [id])\n  userId        String\n  user          User          @relation(fields: [userId], references: [id])\n  paymentMethod PaymentMethod\n  status        InvoiceStatus @default(POSTED)\n  subtotal      Decimal       @db.Decimal(10, 3)\n  taxAmount     Decimal       @default(0) @db.Decimal(10, 3)\n  totalAmount   Decimal       @db.Decimal(10, 3)\n\n  lines        SalesInvoiceLine[]\n  journalEntry JournalEntry?\n\n  createdAt DateTime @default(now())\n}\n\nmodel SalesInvoiceLine {\n  id             String  @id @default(uuid())\n  salesInvoiceId String\n  itemId         String\n  quantity       Decimal @db.Decimal(10, 3)\n  unitPrice      Decimal @db.Decimal(10, 3)\n  lineTotal      Decimal @db.Decimal(10, 3)\n\n  salesInvoice SalesInvoice @relation(fields: [salesInvoiceId], references: [id])\n  item         Item         @relation(fields: [itemId], references: [id])\n}\n",
